begin;
create function pg_temp.check_access(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
insert into auth.users(id) values ('58000000-0000-4000-8000-000000000001'),('58000000-0000-4000-8000-000000000002'),('58000000-0000-4000-8000-000000000003');
insert into public.properties values ('hu58-a','58000000-0000-4000-8000-000000000001','{"name":"Shared","privateCredit":"secret"}',now()),('hu58-b','58000000-0000-4000-8000-000000000002','{}',now());
insert into public.team_members(id,owner_id,member_id,token_hash,payload,updated_at) values ('hu58-g','58000000-0000-4000-8000-000000000001','58000000-0000-4000-8000-000000000003','hu58-token','{"role":"Contratista","status":"Activo","propertyIds":["hu58-a"],"taskIds":["task-a"]}',now());
set local role authenticated;
select set_config('request.jwt.claim.sub','58000000-0000-4000-8000-000000000001',true);
select pg_temp.check_access((select count(*)=1 from public.properties where id in ('hu58-a','hu58-b')),'owner sees only own property');
select set_config('request.jwt.claim.sub','58000000-0000-4000-8000-000000000003',true);
select pg_temp.check_access((select count(*)=0 from public.properties where id in ('hu58-a','hu58-b')),'member cannot read raw property');
select pg_temp.check_access((public.shared_property_summary('hu58-g','hu58-a')->>'name')='Shared' and not(public.shared_property_summary('hu58-g','hu58-a') ? 'privateCredit'),'member summary removes private fields');
select pg_temp.check_access(public.shared_property_summary('hu58-g','hu58-b') is null,'summary rejects unassigned property');
select set_config('request.jwt.claim.sub','58000000-0000-4000-8000-000000000002',true);
select pg_temp.check_access(public.shared_property_summary('hu58-g','hu58-a') is null,'foreign owner cannot borrow grant');
reset role;
update public.team_members set payload=jsonb_set(payload,'{status}','"Revocado"') where id='hu58-g';
set local role authenticated;
select set_config('request.jwt.claim.sub','58000000-0000-4000-8000-000000000003',true);
select pg_temp.check_access(public.shared_property_summary('hu58-g','hu58-a') is null,'revocation checked in database');
reset role;
select pg_temp.check_access(not has_table_privilege('authenticated','public.audit_events','INSERT,UPDATE,DELETE'),'audit not writable through data API');
select pg_temp.check_access(not has_function_privilege('anon','public.shared_property_summary(text,text)','EXECUTE'),'anonymous has no RPC execute');
rollback;
